  const live=$('u-book-live-canvas');let drag=null;
  function livePoint(ev){const rect=live.getBoundingClientRect();return{x:Math.max(.02,Math.min(.98,(ev.clientX-rect.left)/rect.width)),y:Math.max(.02,Math.min(.98,(ev.clientY-rect.top)/rect.height))};}
  live.addEventListener('pointerdown',ev=>{if(!active)return;const p=current(),pt=livePoint(ev);let nearest='main',dist=Math.hypot(pt.x-(p.mainX??.5),pt.y-(p.mainY??.5));for(const e of p.elements){const d=Math.hypot(pt.x-e.x,pt.y-e.y);if(d<dist){nearest=e.id;dist=d;}}if(dist>.32)return;selectedPiece=nearest;drag=ev.pointerId;try{live.setPointerCapture(ev.pointerId);}catch(_){}$('u-palette').hidden=false;showPieceTools();refreshLiveBook();ev.preventDefault();});
